for (int i = 0; i < points.size(); i++) {
    for (int j = i + 1; j < points.size(); j++) {
        double distance = std::sqrt(std::pow(points[i].x - points[j].x, 2) + std::pow(points[i].y - points[j].y, 2));
        if (distance <= 2 * alpha) {
            edges.push_back({{i, j}});
        }
    }
}
std::vector<bool> visited(points.size(), false);
std::vector<std::vector<int>> components;
for (int i = 0; i < points.size(); i++) {
    if (!visited[i]) {
        std::vector<int> component;
        std::vector<int> stack;
        stack.push_back(i);
        visited[i] = true;
        while (!stack.empty()) {
            int node = stack.back();
            stack.pop_back();
            component.push_back(node);
            for (const auto& edge : edges) {
                if (edge.first == node && !visited[edge.second]) {
                    stack.push_back(edge.second);
                    visited[edge.second] = true;
                } else if (edge.second == node && !visited[edge.first]) {
                    stack.push_back(edge.first);
                    visited[edge.first] = true;
                }
            }
        }
        components.push_back(component);
    }
}
for (const auto& component : components) {
    bool isSolid = true;
    for (const auto& point : component) {
        int neighborCount = 0;
        for (const auto& edge : edges) {
            if (edge.first == point || edge.second == point) {
                neighborCount++;
            }
        }
        if (neighborCount < 3) {
            isSolid = false;
            break;
        }
    }
    if (isSolid) {
        count++;
    }
}
return count;

